CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT 'Cinéfilo', avatar_url text);
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_cinetrack_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, display_name) VALUES (new.id, coalesce(nullif(new.raw_user_meta_data->>'display_name',''), nullif(new.raw_user_meta_data->>'name',''), 'Cinéfilo')); RETURN new; END; $$;
CREATE TRIGGER cinetrack_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_cinetrack_profile();
CREATE TABLE public.media_items (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, owner_id uuid NOT NULL DEFAULT auth.uid(), title text NOT NULL, year integer NOT NULL, genre text NOT NULL, poster_url text NOT NULL, type text NOT NULL DEFAULT 'movie' CHECK(type IN ('movie','book')), synopsis text, director text, duration integer);
GRANT SELECT ON public.media_items TO anon;
GRANT SELECT, INSERT ON public.media_items TO authenticated;
GRANT ALL ON public.media_items TO service_role;
ALTER TABLE public.media_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalog_read ON public.media_items FOR SELECT USING (true);
CREATE POLICY catalog_add ON public.media_items FOR INSERT TO authenticated WITH CHECK(owner_id = auth.uid());
CREATE TABLE public.user_media_status (user_id uuid NOT NULL DEFAULT auth.uid(), media_id text NOT NULL, status text NOT NULL DEFAULT 'watchlist' CHECK(status IN ('watched','watching','watchlist')), rating numeric CHECK(rating BETWEEN 0.5 AND 5 AND rating * 2 = trunc(rating * 2)), updated_at date NOT NULL DEFAULT current_date, watched_at date, PRIMARY KEY(user_id, media_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.user_media_status TO authenticated;
GRANT ALL ON public.user_media_status TO service_role;
ALTER TABLE public.user_media_status ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_library ON public.user_media_status FOR ALL TO authenticated USING(user_id = auth.uid()) WITH CHECK(user_id = auth.uid());
CREATE TABLE public.quotes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), media_id text NOT NULL, quote_text text NOT NULL CHECK(length(quote_text) BETWEEN 3 AND 300), timestamp text NOT NULL DEFAULT '—', display_name text NOT NULL DEFAULT 'Cinéfilo', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.quotes TO anon;
GRANT SELECT, INSERT ON public.quotes TO authenticated;
GRANT ALL ON public.quotes TO service_role;
ALTER TABLE public.quotes ENABLE ROW LEVEL SECURITY;
CREATE POLICY quotes_read ON public.quotes FOR SELECT USING(true);
CREATE POLICY quotes_add ON public.quotes FOR INSERT TO authenticated WITH CHECK(user_id = auth.uid());
CREATE TABLE public.activity_feed (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), media_id text NOT NULL, action_type text NOT NULL CHECK(action_type IN ('rated','quoted','started','added')), comment text, rating numeric, display_name text NOT NULL DEFAULT 'Cinéfilo', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.activity_feed TO anon;
GRANT SELECT, INSERT ON public.activity_feed TO authenticated;
GRANT ALL ON public.activity_feed TO service_role;
ALTER TABLE public.activity_feed ENABLE ROW LEVEL SECURITY;
CREATE POLICY feed_read ON public.activity_feed FOR SELECT USING(true);
CREATE POLICY feed_add ON public.activity_feed FOR INSERT TO authenticated WITH CHECK(user_id = auth.uid());